import{_ as a,c as t,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Supported Formats","description":"OME-Zarr and beyond. Find Nuclei Viewer opens OME-Zarr 0.3 to 0.6 in Zarr v2 and v3, HCS plates and labels, Opera Phenix plates from their Harmony index, Yokogawa CellVoyager plates, and analysis bundles. By URL, s3://, folder or zip.","frontmatter":{"title":"Supported Formats","description":"OME-Zarr and beyond. Find Nuclei Viewer opens OME-Zarr 0.3 to 0.6 in Zarr v2 and v3, HCS plates and labels, Opera Phenix plates from their Harmony index, Yokogawa CellVoyager plates, and analysis bundles. By URL, s3://, folder or zip."},"headers":[],"relativePath":"guides/supported-formats.md","filePath":"guides/supported-formats.md"}'),s={name:"guides/supported-formats.md"};function l(n,e,i,d,h,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h1><p>OME-Zarr and beyond. Here is what the viewer opens today, and how.</p><h2 id="ome-zarr" tabindex="-1">OME-Zarr <a class="header-anchor" href="#ome-zarr" aria-label="Permalink to &quot;OME-Zarr&quot;">​</a></h2><p>OME-Zarr is the viewer&#39;s home format. It opens in place: nothing is converted and nothing is uploaded. New to the format? <a href="https://www.find-nuclei.com/blog/why-ome-zarr" target="_blank" rel="noreferrer">Why OME-Zarr Is Taking Over Microscopy</a> covers what it is good for.</p><ul><li><strong>OME-NGFF versions</strong> 0.3, 0.4, 0.5 and 0.6.</li><li><strong>Zarr v2</strong>, uncompressed or compressed with blosc, zlib or gzip.</li><li><strong>Zarr v3</strong>, sharded or not, compressed with blosc, zstd, gzip or zlib.</li><li><strong>Single images</strong>, and datasets with several series from bioformats2raw.</li><li><strong>HCS plates</strong>, with plate, well and field views. See <a href="./hcs-plates.html">HCS Plates</a>.</li><li><strong>Labels</strong> in the image&#39;s <code>labels/</code> group. They load with the image. On a plate, press <strong>Discover</strong>. See <a href="./labels.html">Labels</a>.</li></ul><h3 id="how-it-opens" tabindex="-1">How it opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How it opens&quot;">​</a></h3><ul><li><strong>A web address.</strong> Paste an <code>https://</code> address. The server must allow CORS. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>An <code>s3://</code> address.</strong> Paste <code>s3://bucket/path</code> and the viewer reads the bucket&#39;s public https address. A bucket name with a dot works this way in us-east-1. In other regions, paste its regional https address.</li><li><strong>A folder on your disk</strong>, in Chrome and Edge. See <a href="./local-files.html">Local Files</a>.</li><li><strong>A <code>.ozx</code> or <code>.zip</code> archive</strong>, in any browser. See <a href="./local-files.html#a-dataset-in-a-single-file">A Dataset in a Single File</a>.</li><li><strong>Private data</strong>, with a Bearer token or AWS SigV4. See <a href="./authenticated-sources.html">Authenticated Sources</a>.</li></ul><p>Local or remote? <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> helps you pick.</p><h2 id="opera-phenix-plates" tabindex="-1">Opera Phenix plates <a class="header-anchor" href="#opera-phenix-plates" aria-label="Permalink to &quot;Opera Phenix plates&quot;">​</a></h2><p>Plates exported by Harmony from an Opera Phenix open straight from their index. The Opera Phenix plates of the Cell Painting Gallery open this way, such as the JUMP Cell Painting pilot plate CPJUMP1.</p><ul><li><strong>What opens:</strong> a Harmony index next to its TIFFs: <code>Index.idx.xml</code> (Harmony V5) or <code>Index.xml</code> (Harmony V6).</li><li><strong>From where:</strong> an <code>https://</code> or <code>s3://</code> address, a folder on your disk, or a saved plate manifest.</li><li><strong>What to point at:</strong> the measurement folder, its <code>Images/</code> folder, or the index itself.</li><li><strong>Field view only.</strong> Harmony stores each field at one resolution, so Plate and Well view are off.</li></ul><p>See <a href="./opera-phenix-plates.html">Opera Phenix Plates</a>, and <a href="https://www.find-nuclei.com/blog/opera-phenix-plates-in-the-browser" target="_blank" rel="noreferrer">Opera Phenix Plates in the Browser</a> on our blog for a real JUMP plate.</p><h2 id="yokogawa-cellvoyager-plates" tabindex="-1">Yokogawa CellVoyager plates <a class="header-anchor" href="#yokogawa-cellvoyager-plates" aria-label="Permalink to &quot;Yokogawa CellVoyager plates&quot;">​</a></h2><p>Plates from a Yokogawa CellVoyager CV8000 or CV7000 open straight from their measurement folder. More than 1,000 JUMP Cell Painting plates in the Cell Painting Gallery come from a CellVoyager CV8000 or CV7000 and open this way.</p><ul><li><strong>What opens:</strong> <code>MeasurementDetail.mrf</code>, the <code>.mes</code> file it names and <code>MeasurementData.mlf</code>, next to their TIFFs.</li><li><strong>From where:</strong> an <code>https://</code> or <code>s3://</code> address, or a folder on your disk.</li><li><strong>What to point at:</strong> the measurement folder, <code>MeasurementDetail.mrf</code> or <code>MeasurementData.mlf</code>.</li><li><strong>Field view only,</strong> and plane 1 of every channel.</li><li><strong>Not yet:</strong> folders without <code>MeasurementDetail.mrf</code>, and the Yokogawa CQ1.</li></ul><p>See <a href="./yokogawa-plates.html">Yokogawa CellVoyager Plates</a>.</p><h2 id="companion-data" tabindex="-1">Companion data <a class="header-anchor" href="#companion-data" aria-label="Permalink to &quot;Companion data&quot;">​</a></h2><ul><li><strong>Label masks</strong> that live outside the image: a Zarr label array from a URL, or from a folder in Chrome and Edge. See <a href="./labels.html">Labels</a>.</li><li><strong>Measurements and analysis bundles:</strong> a CSV or Parquet table with one row per object, up to a run manifest that lists several masks and tables, all from one URL. A table also opens from your disk in Chrome and Edge. See <a href="./analytics-format.html">Analytics Data Format</a>, and <a href="https://www.find-nuclei.com/blog/hcs-analytics-in-the-browser" target="_blank" rel="noreferrer">HCS Analytics in the Browser</a> for a real screen.</li><li><strong>Plate manifests:</strong> a small JSON file that describes an Opera Phenix or Yokogawa CellVoyager plate. Save one from the viewer and open it by URL. The format is a published JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">plate-manifest/v1.json</a>.</li></ul><h2 id="which-browser-opens-what" tabindex="-1">Which browser opens what <a class="header-anchor" href="#which-browser-opens-what" aria-label="Permalink to &quot;Which browser opens what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you open</th><th>Chrome, Edge</th><th>Firefox, Safari</th></tr></thead><tbody><tr><td>A web address: image, plate, label, table or bundle</td><td>Yes</td><td>Yes</td></tr><tr><td>An <code>s3://</code> address of an image or plate</td><td>Yes</td><td>Yes</td></tr><tr><td>A dataset zipped into one <code>.ozx</code> or <code>.zip</code> file</td><td>Yes</td><td>Yes</td></tr><tr><td>A folder: OME-Zarr, Opera Phenix plate, Yokogawa CellVoyager plate or label</td><td>Yes</td><td>No</td></tr><tr><td>A measurement table from your disk</td><td>Yes</td><td>No</td></tr></tbody></table><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><p>Other vendor formats open after conversion to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><p>Which format should we add next? Tell us at <a href="mailto:info@find-nuclei.com" target="_blank" rel="noreferrer">info@find-nuclei.com</a>.</p>',23)])])}const g=a(s,[["render",l]]);export{m as __pageData,g as default};
